"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        result = plan(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

journal.py.text:
"""Normalize release records at the input boundary.

This module owns change input validation, replay identity (deduplication vs.
conflict), the persisted `applied` journal, and the dependency graph. It never
orders actions or judges budget; those belong to planner/policy.
"""


class JournalError(ValueError):
    pass


# Field keys are validated one at a time so a malformed field never short-circuits
# into the wrong code (e.g. a bad `depends_on` must not mask as "invalid-change"
# before we know the record shape is otherwise usable). All shape errors here map
# to the single `invalid-change` code required by the spec.
def _require_text(record, key):
    value = record.get(key)
    if not isinstance(value, str) or not value:
        raise JournalError("invalid-change")
    return value


def _require_units(record):
    units = record.get("units")
    # `type(...) is int` (not isinstance) rejects bools, which are ints in Python.
    if type(units) is not int or units < 1:
        raise JournalError("invalid-change")
    return units


def _id_list(record, key):
    """Return de-duplicated IDs in first-seen order; default is an empty list."""
    if key not in record:
        return []
    value = record[key]
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    seen = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        if item not in seen:
            seen.append(item)
    return seen


def _parse_change(row):
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    return {
        "id": _require_text(row, "id"),
        "component": _require_text(row, "component"),
        "units": _require_units(row),
        "depends_on": _id_list(row, "depends_on"),
    }


def read_changes(records):
    """Normalize, then collapse equal records and reject conflicting duplicates.

    Replay identity is (id, component, units, set(depends_on)): dependency order
    is irrelevant, so ["a","b"] and ["b","a"] are the same record. Collapsing
    happens here, before accounting and graph construction, so a duplicate can
    never consume budget twice or add a second edge. Two records that share an
    id but differ in any of those fields are a real conflict, because either
    version could be the authenticated release and silently picking one would
    change the plan.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        change = _parse_change(row)
        key = (change["component"], change["units"], frozenset(change["depends_on"]))
        previous = changes.get(change["id"])
        if previous is None:
            changes[change["id"]] = change
        elif (previous["component"], previous["units"],
              frozenset(previous["depends_on"])) != key:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(value):
    """Validate the caller-supplied release journal: a list of unique change IDs."""
    if value is None:
        return []
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    applied = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        if item not in applied:
            applied.append(item)
    return applied


def build_graph(changes, applied):
    """Return (deps, dependents) adjacency keyed by change id.

    `deps[c]` lists the change ids `c` directly depends on. `depends_on[i] -> c`
    is the execution edge (dependency first). A dependency on an applied change
    is satisfied and contributes no new sequencing edge, but the target must
    still be a declared change: an unknown name is a broken journal, not a no-op.
    """
    known = {change["id"] for change in changes}
    applied_set = set(applied)
    for target in applied:
        if target not in known:
            raise JournalError("unknown-dependency")
    deps = {}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        edges = []
        for target in change["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
            if target in applied_set:
                continue
            edges.append(target)
            dependents[target].append(change["id"])
        deps[change["id"]] = edges
    return deps, dependents


def topological_order(deps, dependents):
    """Deterministic Kahn order: among all ready ids, always take the smallest.

