"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def validate(request):
    """Run every policy/journal check and return the normalized inputs.

    Ordered replay-first: dedupe and resolve ``applied`` before any accounting,
    so ``units`` and the graph describe the logical changes rather than the
    raw request. Every check runs before an action can be emitted, so a late
    failure never leaves a partial result behind.
    """
    budget = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request, changes)
    return budget, changes, applied


def build_graph(changes):
    """Map each change ID to the IDs it directly blocks (dependents).

    Graph direction: ``depends_on`` points at the prerequisite, so an edge
    runs prerequisite -> dependent. Sorting therefore waits on a change's
    prerequisites; a missing target means the request names a prerequisite it
    never defines, which is unresolvable without guessing.
    """
    known = {change["id"] for change in changes}
    dependents = {change_id: [] for change_id in known}
    indegree = {change_id: 0 for change_id in known}
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
            dependents[dep].append(change["id"])
            indegree[change["id"]] += 1
    return dependents, indegree


def topological_order(changes):
    """Return the full deterministic order over every change.

    Determinism: among changes whose prerequisites are all placed, the
    lexicographically smallest ID is always taken next, so the same request
    always yields the same order regardless of input order. Stopping short of
    ``len(changes)`` means some change still waits on a prerequisite, which on
    a finite graph is only possible when a cycle exists.
    """
    dependents, indegree = build_graph(changes)
    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget, changes, applied = validate(request)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    by_id = {change["id"]: change for change in changes}
    if request.get("action") == "rollback":
        # Reverse order guarantees dependents come down before the changes
        # they depend on; only live changes are reverted.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # An applied change is already live, so it satisfies dependencies and
        # consumes no new budget; only the remaining ones are planned.
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    try:
        check_budget(request.get("action"), budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

