"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    # Every failure must be this exact shape with no partial actions, so callers
    # can treat any non-ok result as "nothing was decided".
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(ids, units):
    return {"status": "ok", "actions": ids, "units": units}


def collapse(changes):
    """Fold identical records to one; reject ids that disagree on content.

    Identity covers id, component, units, and the *set* of dependencies: replay
    may reorder a record's depends_on list without meaning anything different.
    """
    unique = {}
    for row in changes:
        identity = (row["id"], row["component"], row["units"], frozenset(row["depends_on"]))
        if row["id"] in unique:
            if unique[row["id"]] != identity:
                raise JournalError("conflicting-change")
        else:
            unique[row["id"]] = identity
    # Keep one canonical record per id, with dependencies deduplicated so the
    # graph does not count a repeated edge twice.
    return {cid: {"id": cid, "component": rec[1], "units": rec[2], "depends_on": rec[3]}
            for cid, rec in unique.items()}


def build_graph(changes, applied):
    """Map each id to the ids it directly requires.

    Graph direction: an edge points from a change to the change it depends on, so
    "ready" means a node whose dependency set is entirely satisfied.
    """
    known = set(changes)
    edges = {}
    for cid, row in changes.items():
        for dep in row["depends_on"]:
            # Unknown targets fail closed rather than being assumed absent.
            if dep not in known:
                raise JournalError("unknown-dependency")
            edges.setdefault(cid, set()).add(dep)
    # The persisted journal may only name changes this request knows about;
    # anything else means our view of the world is stale, so refuse to plan.
    for cid in applied:
        if cid not in known:
            raise JournalError("unknown-dependency")
    return edges


def topological_order(changes, edges):
    """Kahn's algorithm, always taking the lexicographically smallest ready id.

    Applied history is irrelevant here: the order is a property of the graph, and
    both plan and rollback derive from this single deterministic sequence.
    """
    remaining = {cid: set(deps) for cid, deps in edges.items()}
    for cid in changes:
        remaining.setdefault(cid, set())
    order = []
    # A heap keeps the ready set ordered without re-sorting on every step.
    ready = [cid for cid, deps in remaining.items() if not deps]
    heapq.heapify(ready)
    waiting = sorted(remaining)
    dependents = {cid: [] for cid in waiting}
    for cid in waiting:
        for dep in remaining[cid]:
            dependents[dep].append(cid)
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for parent in iter(dependents[cid]):
            remaining[parent].discard(cid)
            if not remaining[parent]:
                heapq.heappush(ready, parent)
    # Any node never emitted is either on or behind a cycle; report it as such no
    # matter where in the graph it sits.
    if len(order) != len(remaining):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        # Replay first: duplicates must collapse before units reach the budget,
        # otherwise a replayed request looks like new spend.
        changes = collapse(changes)
        graph = build_graph(changes, applied)
        order = topological_order(changes, graph)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if action == "plan":
        applied_ids = set(applied)
        # Already applied entries still satisfy dependencies but consume no new
        # budget, so drop them before summing.
        emitted = [cid for cid in order if cid not in applied_ids]
        units = sum(changes[cid]["units"] for cid in emitted)
        if units > budget:
            return failure("budget-exceeded")
        return success(emitted, units)

    # Rollback: reverse of the full deterministic order, restricted to what was
    # actually released. The budget is validated above but never caps rollback --
    # undoing a release must not be blocked by a spending limit.
    applied_ids = set(applied)
    emitted = [cid for cid in reversed(order) if cid in applied_ids]
    return success(emitted, sum(changes[cid]["units"] for cid in emitted))

