    both plan and rollback derive from this single deterministic sequence.
    """
    remaining = {cid: set(deps) for cid, deps in edges.items()}
    for cid in changes:
        remaining.setdefault(cid, set())
    order = []
    # A heap keeps the ready set ordered without re-sorting on every step.
    ready = [cid for cid, deps in remaining.items() if not deps]
    heapq.heapify(ready)
    waiting = sorted(remaining)
    dependents = {cid: [] for cid in waiting}
    for cid in waiting:
        for dep in remaining[cid]:
            dependents[dep].append(cid)
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for parent in iter(dependents[cid]):
            remaining[parent].discard(cid)
            if not remaining[parent]:
                heapq.heappush(ready, parent)
    # Any node never emitted is either on or behind a cycle; report it as such no
    # matter where in the graph it sits.
    if len(order) != len(remaining):
        raise JournalError("dependency-cycle")
    return order


def retained_ids(retain, applied, graph):
    """Expand a retain list to the changes that must stay released.

    Retention is transitive: keeping a change while reverting something it
    depends on would leave a released change without its prerequisite, so every
    dependency of a retained change is retained too. Only applied dependencies
    are followed; an unapplied one was never released and needs no protection.
    """
    applied_ids = set(applied)
    # Retain may only name changes that are already applied; anything else means
    # the caller's view of the release differs from the journal, so refuse.
    for cid in retain:
        if cid not in applied_ids:
            raise JournalError("invalid-retain")
    keep = set()
    pending = [cid for cid in retain if cid in applied_ids]
    while pending:
        cid = pending.pop()
        if cid in keep:
            continue
        keep.add(cid)
        for dep in graph.get(cid, ()):
            if dep in applied_ids and dep not in keep:
                pending.append(dep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # limit_for is called first on purpose: G2's production freeze must win
        # over every change/graph defect, so this call cannot move below the
        # journal reads.
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        # retain is rollback-only; validating it for plan would reject requests
        # whose retain field the plan path never consults.
        retain = read_retain(request.get("retain")) if action == "rollback" else []
        # Replay first: duplicates must collapse before units reach the budget,
        # otherwise a replayed request looks like new spend.
        changes = collapse(changes)
        graph = build_graph(changes, applied)
        order = topological_order(changes, graph)
        keep = retained_ids(retain, applied, graph) if action == "rollback" else set()
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if action == "plan":
        applied_ids = set(applied)
        # Already applied entries still satisfy dependencies but consume no new
        # budget, so drop them before summing. budget is already the effective
        # staging limit from policy, not the raw request value.
        emitted = [cid for cid in order if cid not in applied_ids]
        units = sum(changes[cid]["units"] for cid in emitted)
        if units > budget:
            return failure("budget-exceeded")
        return success(emitted, units)

    # Rollback: reverse of the full deterministic order, restricted to what was
    # actually released, then filtered against the retained set. Filtering the
    # original sequence (rather than re-sorting the survivors) preserves G1's
    # reverse order. The budget is validated above but never caps rollback --
    # undoing a release must not be blocked by a spending limit.
    applied_ids = set(applied)
    emitted = [cid for cid in reversed(order)
               if cid in applied_ids and cid not in keep]
    return success(emitted, sum(changes[cid]["units"] for cid in emitted))

