"""Compose policy and journal data into a plan.

Owns the dependency graph, the deterministic order and the final result shape.
Every rejection returns the same closed shape and no actions, so a caller never
sees a partially emitted plan.
"""
from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


class GraphError(ValueError):
    pass


def full_order(changes):
    """Return the complete deterministic topological order of every change.

    Edges point the way the work runs: an entry lists the IDs it waits for, so
    edges go from dependency to dependent. Waiting IDs are looked up here -- an
    ID nothing defines is ``unknown-dependency``. A residual graph means a cycle
    somewhere, not only among emitted entries, hence ``dependency-cycle``.

    Among all currently eligible changes the smallest ID is taken first. Already
    applied changes take part in this ordering like any other node, which is
    what keeps both the plan suffix and its rollback mirror stable.
    """
    known = {change["id"] for change in changes}
    waiting = {}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        deps = set(change["depends_on"])
        if not deps <= known:
            raise GraphError("unknown-dependency")
        waiting[change["id"]] = set(deps)
        for dep in deps:
            dependents[dep].append(change["id"])
    eligible = sorted(change_id for change_id, deps in waiting.items() if not deps)
    order = []
    while eligible:
        change_id = eligible.pop(0)
        order.append(change_id)
        for dependent in dependents[change_id]:
            waiting[dependent].discard(change_id)
            if not waiting[dependent]:
                eligible.append(dependent)
        eligible.sort()
    if len(order) != len(changes):
        raise GraphError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if not applied <= set(units_by_id):
        return failure("unknown-dependency")
    try:
        order = full_order(changes)
    except GraphError as exc:
        return failure(str(exc))
    if request["action"] == "rollback":
        # Undo runs against the same full order reversed, so applied entries are
        # still taken in the exact inverse of their rollout sequence; unapplied
        # entries never reached the environment and are simply skipped.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Applied entries are already in place: they satisfy their dependents
        # instead of being emitted again, and their units stay out of ``units``
        # so the budget is charged for new work only.
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in actions)
    try:
        check_budget(request["action"], budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

